use std::fs

fn parse_line(line: string) -> string {
    let cs = line.chars().collect::<Vec<char>>()
    let n = cs.len()
    let mut fields: Vec<string> = Vec::new()
    let mut cur = ""
    let mut inq = false
    let mut i = 0
    while i < n {
        let c = cs[i]
        if inq {
            if c == '"' {
                if i + 1 < n && cs[i + 1] == '"' {
                    cur = cur + "\""
                    i += 1
                } else {
                    inq = false
                }
            } else {
                cur = cur + c.to_string()
            }
        } else if c == '"' {
            inq = true
        } else if c == ',' {
            fields.push(cur)
            cur = ""
        } else {
            cur = cur + c.to_string()
        }
        i += 1
    }
    fields.push(cur)
    let mut out = "${fields.len()}: "
    let mut k = 0
    while k < fields.len() {
        if k > 0 {
            out = out + "|"
        }
        out = out + "[" + fields[k] + "]"
        k += 1
    }
    out
}

fn main() {
    let r = fs::read_to_string("/dev/stdin")
    match r {
        Ok(t) => {
            for line in t.lines() {
                let l = line.trim_end_matches("\r")
                println(parse_line(l.to_string()))
            }
        },
        Err(e) => println("err ${e}"),
    }
}

